#!/usr/bin/env python3
"""Build an offline interactive comparison and source/evidence inspector."""
import argparse
import base64
import json
from pathlib import Path
from evaluate import bind, score

HTML = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Beier Catalog experiment</title><style>
:root{font:15px/1.5 system-ui;color:#172c33;background:#f2f5f3}body{margin:0}header{padding:28px 36px;background:#173e44;color:white}h1{margin:0;font-size:30px}header p{max-width:1050px;color:#d0e8e6}main{padding:24px 36px}section{background:white;border:1px solid #d9e3df;border-radius:10px;padding:20px;margin-bottom:20px}h2{font-size:20px;margin:0 0 12px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #e0e7e4;padding:9px;text-align:left;vertical-align:top}th{color:#41625c;background:#f7faf8;position:sticky;top:0}button,select{font:inherit;border:1px solid #b7c9c3;border-radius:5px;padding:6px 9px;background:white;color:inherit;cursor:pointer}button:hover{background:#e6f1ed}.bad{background:#fff0ed}.good{background:#edf8f2}.warn{background:#fff8df}.muted{color:#62736e;font-size:13px}.scroll{overflow:auto;max-height:520px}.workspace{display:grid;grid-template-columns:minmax(430px,1fr) minmax(620px,1.35fr);gap:18px}.page{position:relative}.page img{width:100%;display:block}.box{position:absolute;border:2px solid #e17b25;background:#e17b2518;box-sizing:border-box;pointer-events:none}.box.gold{border-color:#1e8868;background:#1e88680f}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 system-ui;max-height:300px;overflow:auto}.legend span{padding:3px 9px;border-radius:4px;margin-right:8px}.pill{font-size:12px;background:#e5efeb;padding:3px 7px;border-radius:10px}label{display:inline-block;margin-right:12px}td button{max-width:260px;text-align:left;width:100%;font-size:12px;border-color:transparent;background:transparent}.note{border-left:4px solid #d99d30;padding:8px 12px;background:#fff8e5}.num{white-space:nowrap}@media(max-width:1100px){.workspace{display:block}main{padding:16px}header{padding:24px}}
.flow{display:flex;align-items:stretch;gap:12px;overflow:auto;padding:12px 0}.stage{min-width:165px;flex:1;border:1px solid #bdd6cc;background:#f1f8f4;border-radius:8px;padding:12px}.stage b{display:block;margin:6px 0}.arrow{align-self:center;color:#4b8577;font-size:24px}.stage small{display:block;color:#49655d}.stage .pill{display:inline-block}
</style><header><h1>Beier Catalog: fewer calls, checked evidence</h1><p>29 numbered entries · 7 fields · 3 scanned book spreads. Every strategy uses the same parser snapshot. Reference answers were checked by the agent against the supplied PDF; they have not been independently adjudicated by a researcher.</p></header><main>
<section><h2>Pipeline and prompts</h2><label>Strategy <select id="pipeline"><option value="current">Current Catalog pipeline</option><option value="joint">Combined extraction and evidence</option><option value="hybrid">NuExtract batches + code + selective Luna</option><option value="chunk">Combined discovery, extraction and evidence</option></select></label><label id="batch-control" hidden>Records per batch <select id="batch"><option>1</option><option selected>3</option><option>5</option><option>10</option></select></label><div class="flow" id="flow"></div><p class="muted" id="flow-note"></p></section>
<section><h2>Comparison</h2><p class="muted">Times exclude the shared parsing step reported below. Accuracy includes missing fields and records. Supported accuracy requires both a correct value and an annotated supporting anchor. Hover names for settings. Rows with reused discovery include its recorded time and calls in the full-pipeline estimate; they are not fresh end-to-end timing measurements.</p><div class="scroll"><table id="summary"></table></div><p class="muted">Luna and NuExtract run on different infrastructure. Compare strategies within a model as well as the practical hybrid. Call counts are application/provider invocations, not hidden infrastructure requests.</p></section>
<section><h2>Parsing check</h2><div class="note">The parser preserved all visible starts 205–233 in order, but the transcription is not clean. Entry 213 has displaced sentence fragments; the continuation of 214 has interleaved fragments; entry 225 reads “Groβkorbetha” with Greek beta instead of printed “Großkorbetha”. Accuracy against the PDF remains the primary measure.</div><p id="parsing" class="muted"></p><p class="muted">Cross-page anchor 214 spans PDF spreads 1 and 2. A box being within page bounds does not establish correct OCR or semantic evidence.</p></section>
<section><h2>Inspect a result against the PDF</h2><label>Run <select id="run"></select></label><label><input type="checkbox" id="errors" checked> Only disagreements</label><p class="muted">Click a field to inspect its returned and expected evidence. An empty evidence list is an abstention; an existing but wrong anchor is an error.</p>
<div class="workspace"><div><div class="scroll"><table id="detail"></table></div><h3 id="selected">Select a field</h3><pre id="text"></pre><details><summary>Run failures, duplicate and extra records</summary><pre id="record-errors"></pre></details></div><div><label>PDF spread <select id="page"></select></label><p class="legend"><span style="background:#fff0dc">Orange: returned evidence</span><span style="background:#e2f6ec">Green: expected evidence</span></p><div id="source" class="page"><img id="page-image" alt="Original scanned catalog spread"><div id="overlays"></div></div></div></div></section>
<section><h2>Scope and reproducibility</h2><p>This tests one historical catalog and seven selected fields. It does not establish accuracy for artefact lists, arbitrary catalogs, tables, or other OCR failures. Candidate strategies were developed on IDs 205–214. The whole PDF and initial full-baseline results were visible before the freeze. IDs 215–233 are an additional reported subset, not a blind holdout. Formatting examples are synthetic and contain no Beier answers. The header rule and field-aware linker use Beier’s printed Fdpl./Mbl./FA conventions. Batch sizes 1, 3 and 10 were explored after the original full-excerpt comparison. Some late batch-size trials failed when the local Luna CLI rejected a table-valued context_management feature. The saved configuration subsequently changed outside this experiment and normal execution resumed. Failed compatibility-wrapper attempts remain in the manifests; they are not successful pipeline timings.</p><details><summary>Input hashes and run manifests</summary><pre id="provenance"></pre></details></section></main>
<script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent), el=id=>document.getElementById(id), fmt=x=>(100*x).toFixed(1)+'%', seconds=x=>(x/1000).toFixed(1);
const E=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}, add=(parent,...children)=>children.forEach(c=>parent.appendChild(c));
const heads=(table,cols)=>{const tr=E('tr');cols.forEach(c=>tr.appendChild(E('th',c)));table.appendChild(tr)};

const pipelines={
current:{stages:[['Shared preparation','Parse PDF','OCR and layout → ordered blocks, canonical anchors and PDF boxes. No extraction LLM request.'],['3 LLM calls','Discover records','Block-labelled chunks + record definition → starts and end. Code validates boundaries.'],['29 LLM calls','Extract values','One complete record + schema instructions → values only.'],['Code','Checkpoint','Save extracted values before grounding.'],['29 LLM calls','Link evidence','Claims + candidate E-labelled passages → C-to-E links or NONE. Code validates selections.']],note:'Observed here: 61 calls, no document-scoped extraction fields, no discovery correction retries. Document fields, discovery correction retries, failed records and empty claims can change this count. Code: packages/extraction/src/module.ts, source-context.ts, grounding.ts and Studio api/_model.ts.'},
joint:{stages:[['Shared preparation','Parse PDF','Exactly the same frozen parser snapshot.'],['3 reused calls','Discover records','Validated boundaries from the Luna baseline; its calls and time remain in totals.'],['29 or 6 calls','Values + evidence','One record or five records per call. Exact E labels accompany the values in the same JSON response.'],['Code','Validate anchors','Reject nonexistent or out-of-scope labels; semantic support is measured against the reference.']],note:'NuExtract uses one native prompt example containing two synthetic records. A valid anchor label can still cite the wrong passage.'},
hybrid:{stages:[['Shared preparation','Parse PDF','Exactly the same frozen parser snapshot.'],['Code or 3 reused calls','Find boundaries','Beier numbered Fdpl. headers, or reuse Luna discovery for a separate comparison.'],['6 NuExtract calls','Extract five records','Values-only schema + one example with two synthetic records. No evidence-label generation.'],['Code','Link unique evidence','Use field-specific printed conventions. Abstain if evidence is absent or ambiguous.'],['0 or 1 Luna call','Resolve abstentions','Only unresolved populated claims + their record sources → E labels. Values are not rewritten.']],note:'This linker and boundary rule are specific to the Beier format. Selective fallback cannot recover missing values or correct wrong values already linked by code.'},
chunk:{stages:[['Shared preparation','Parse PDF','Exactly the same frozen parser snapshot.'],['3 LLM calls','Discover + extract + link','One call per page/size chunk. Labelled source + adjacent continuation context → record starts, values and evidence.'],['Code','Validate and score','Keep duplicate and spurious records visible. Check start anchors and field evidence against source-reviewed answers.']],note:'The fewest calls tested, but latency and accuracy depend on output size and model behavior. A low call count is not itself a successful result.'}
};
function renderFlow(){const mode=el('pipeline').value,p=structuredClone(pipelines[mode]),root=el('flow');el('batch-control').hidden=mode!=='hybrid';if(mode==='hybrid'){const n=Number(el('batch').value);p.stages[2][0]=Math.ceil(29/n)+' NuExtract calls';p.stages[2][1]='Extract '+n+' record'+(n===1?'':'s')+' per call'}root.replaceChildren();p.stages.forEach((s,i)=>{if(i)root.appendChild(E('div','→','arrow'));const card=E('div',undefined,'stage');add(card,E('span',s[0],'pill'),E('b',s[1]),E('small',s[2]));root.appendChild(card)});el('flow-note').textContent=p.note}el('pipeline').onchange=renderFlow;el('batch').onchange=renderFlow;renderFlow();
heads(el('summary'),['Run','Status','Records','Field accuracy','Supported accuracy','Evidence precision','Calls: executed / full','Time: measured / full estimate','Input / output tokens']);
data.runs.forEach((r,i)=>{const m=r.metrics,tr=E('tr');const b=E('button',r.name);b.title=JSON.stringify(r.settings);b.onclick=()=>{el('run').value=i;renderDetails();el('detail').scrollIntoView({behavior:'smooth'})};const td=E('td');td.appendChild(b);add(tr,td,E('td',m.failure?'FAILED':'Complete'),E('td',`${m.correctUniqueRecords}/${m.expectedRecords} unique · ${m.returnedRecords} returned${m.duplicates?' · duplicates '+m.duplicates:''}${m.spuriousRecords?' · extra '+m.spuriousRecords:''}`),E('td',fmt(m.fieldAccuracy)),E('td',fmt(m.supportedAccuracy)),E('td',fmt(m.evidencePrecision)),E('td',`${m.executedCalls} / ${m.fullPipelineCalls}`,'num'),E('td',`${seconds(m.measuredWallMs)}s / ${seconds(m.fullPipelineWallMs)}s`,'num'),E('td',`${m.inputTokens.toLocaleString()} / ${m.outputTokens.toLocaleString()}`));if(m.failure)tr.className='bad';el('summary').appendChild(tr);const o=E('option',r.name);o.value=i;el('run').appendChild(o)});
data.pages.forEach((p,i)=>{const o=E('option',`${i+1} (printed ${128+i*2}–${129+i*2})`);o.value=i;el('page').appendChild(o)});
el('parsing').textContent=`${data.input.pageCount} PDF spreads; ${data.input.blockCount} canonical blocks; ${data.input.anchorCount} anchors; ${data.input.observationCount} location observations; ${data.input.outOfBoundsObservations.length} boxes outside their page bounds. Parser time: ${seconds(data.parseMs)} seconds.`;
el('provenance').textContent=JSON.stringify({input:data.input,runs:data.runs.map(r=>({name:r.name,settings:r.settings,codeHashes:r.codeHashes,runtime:r.runtime})),freeze:data.freeze,runtimeVersions:data.runtimeVersions,cliProbe:data.cliProbe},null,2);
let returned=[],expected=[];
function renderPage(){const n=Number(el('page').value);el('page-image').src=data.pages[n];el('overlays').replaceChildren();for(const [ids,gold]of [[returned,false],[expected,true]])for(const id of ids){for(const o of data.anchors[id]?.producer_observations??[]){if(o.page_number!==n+1||!o.bbox)continue;const p=data.pageSizes[n],b=o.bbox,d=E('div',undefined,'box'+(gold?' gold':''));Object.assign(d.style,{left:b.x0/p.width_pt*100+'%',top:b.y0/p.height_pt*100+'%',width:(b.x1-b.x0)/p.width_pt*100+'%',height:(b.y1-b.y0)/p.height_pt*100+'%'});el('overlays').appendChild(d)}}}
function inspect(number,field,row,gold,issue){returned=row?.evidence?.[field]??[];expected=gold.evidence[field];el('selected').textContent=`Entry ${number} · ${field}`;el('text').textContent=JSON.stringify({expected:gold.values[field],actual:row?.values?.[field]??null,valueCorrect:issue?issue.valueCorrect:true,returnedEvidence:returned.map(id=>({id,text:data.anchorTexts[id]})),expectedEvidence:expected.map(id=>({id,text:data.anchorTexts[id]}))},null,2);const a=data.anchors[returned[0]??expected[0]];if(a?.producer_observations?.length)el('page').value=a.producer_observations[0].page_number-1;renderPage()}
function renderDetails(){const r=data.runs[Number(el('run').value)],t=el('detail');t.replaceChildren();returned=[];expected=[];el('selected').textContent='Select a field';el('text').textContent='';renderPage();const ids=new Set(data.reference.rows.map(x=>x.values.catalog_number));const badRows=r.rows.filter(x=>!ids.has(x.values.catalog_number)||r.rows.filter(y=>y.values.catalog_number===x.values.catalog_number).length>1);el('record-errors').textContent=JSON.stringify({failure:r.metrics.failure,missingOrDuplicateIds:r.metrics.missingRecords,truncatedCalls:r.metrics.truncatedCalls,invalidSelections:r.metrics.invalidSelections,rows:badRows},null,2);heads(t,['Entry / field','Returned value','Expected']);for(const gold of data.reference.rows){const n=gold.values.catalog_number,matches=r.rows.filter(x=>x.values.catalog_number===n),row=matches.length===1?matches[0]:null;for(const field of data.reference.columns){const issue=r.metrics.issues.find(x=>x.catalog_number===n&&x.field===field);if(el('errors').checked&&!issue)continue;const tr=E('tr',undefined,issue?(issue.valueCorrect?'warn':'bad'):'good'),name=E('button',`${n} · ${field}`);name.onclick=()=>inspect(n,field,row,gold,issue);const td=E('td');td.appendChild(name);add(tr,td,E('td',matches.length>1?'Duplicate record':JSON.stringify(row?.values?.[field]??null)),E('td',JSON.stringify(gold.values[field])));t.appendChild(tr)}}if(t.children.length===1){const tr=E('tr'),td=E('td','No disagreements in the annotated fields.');td.colSpan=3;tr.appendChild(td);t.appendChild(tr)}}
el('run').onchange=renderDetails;el('errors').onchange=renderDetails;el('page').onchange=renderPage;renderDetails();renderPage();
</script></html>'''


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--input-dir', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('runs', type=Path, nargs='+')
    args = parser.parse_args()
    root = args.input_dir
    document_path = root / 'parsed_document.json'
    document = json.loads(document_path.read_bytes())
    reference = bind(document_path)
    runs = []
    for path in args.runs:
        run = json.loads(path.read_text())
        metrics = score(run, reference, 'all')
        path.with_name('metrics-all.json').write_text(json.dumps(metrics, ensure_ascii=False, indent=2))
        evaluation = score(run, reference, 'evaluation')
        path.with_name('metrics-evaluation.json').write_text(json.dumps(evaluation, ensure_ascii=False, indent=2))
        runs.append({'name': path.parent.name, 'settings': {k: run.get(k) for k in ['strategy','model','batch-size','few-shot','field-aware','fallback-model','ground-model','discovery-from']},
                     'codeHashes': run.get('codeHashes'), 'runtime': json.loads(path.with_name('runtime.json').read_text()) if path.with_name('runtime.json').exists() else None,
                     'rows': run['rows'], 'metrics': metrics, 'evaluation': evaluation})
    blocks = {b['block_id']: b for b in document['content_stream']}
    anchors = {a['anchor_id']: a for a in document['evidence_index']['anchors']}
    texts = {key: blocks[a['block_id']].get('text', '') for key, a in anchors.items() if a['kind'] == 'text'}
    payload = {'runs': runs, 'reference': reference, 'input': json.loads((root/'input-manifest.json').read_text()),
               'parseMs': json.loads((root/'parse-status.json').read_text())['stats']['docling']['duration_ms'],
               'anchors': anchors, 'anchorTexts': texts, 'pageSizes': document['pages'],
               'pages': ['data:image/png;base64,' + base64.b64encode(p.read_bytes()).decode() for p in sorted(root.glob('page-*.png'))],
               'freeze': json.loads((root/'freeze.json').read_text()) if (root/'freeze.json').exists() else None,
               'runtimeVersions': json.loads((root/'runtime-versions.json').read_text()) if (root/'runtime-versions.json').exists() else None,
               'cliProbe': json.loads((root/'cli-config-probe.json').read_text()) if (root/'cli-config-probe.json').exists() else None}
    args.out.write_text(HTML.replace('__DATA__', json.dumps(payload, ensure_ascii=False).replace('<', '\\u003c')))
    args.out.with_suffix('.json').write_text(json.dumps({'runs': [{k:v for k,v in r.items() if k != 'rows'} for r in runs], 'input': payload['input']}, ensure_ascii=False, indent=2))
    print(args.out)


if __name__ == '__main__':
    main()
